              (apptStartMinutes <= timeSlotMinutes && apptEndMinutes >= timeSlotEndMinutes)
            );

            if (hasOverlap) {
              console.log(`Time conflict: ${timeSlot} conflicts with appointment at ${appt.start_time}`);
            }

            return hasOverlap;
          });
        });

