  // Handle worker selection (step 3)
  if (ctx.step === 3) {
    const workers = getSuggestedOptions(ctx);
    if (workers && optionIndex >= 0 && optionIndex < workers.length) {
      processedText = workers[optionIndex];
    }
  }

  // Handle confirmation (step 6)
  if (ctx.step === 6) {
    if (optionIndex === 0) processedText = 'sim';
    if (optionIndex === 1) processedText = 'não';
  }

  // Handle time selection (step 5)
  if (ctx.step === 5 && timeOptions.length > 0) {
    if (optionIndex >= 0 && optionIndex < timeOptions.length) {
      processedText = timeOptions[optionIndex];
    }
  }

  // Handle date selection (step 4)
  if (ctx.step === 4 && dateOptions.length > 0) {
    if (optionIndex >= 0 && optionIndex < dateOptions.length) {
      // Convert from display format to YYYY-MM-DD
      const displayDate = dateOptions[optionIndex];
      const formatDate = (displayStr) => {
        // Extract the date from something like "qua., 14/05"
        const match = displayStr.match(/(\d{2})\/(\d{2})/);
        if (match) {
          const day = match[1];
          const month = match[2];
