        let isValidDate = false;

        // Check for recognizable date formats
        if (enteredText.match(/^\d{1,2}\/\d{1,2}(\/\d{4})?$/) || // DD/MM/YYYY or DD/MM
            enteredText.match(/^\d{4}-\d{1,2}-\d{1,2}$/) ||      // YYYY-MM-DD
            enteredText === 'hoje' || enteredText === 'today' || 
