          // Add available time slot
          if (isAvailable) {
            times.push(timeSlot);
          }

          // Move to next time slot
          currentMinute += interval;
          if (currentMinute >= 60) {
            currentHour += 1;
            currentMinute -= 60;
          }
        }

        console.log(`Generated ${times.length} available times from scratch`);
        setAvailableTimes(times);
